actions.script:
datasetId=datasetId || 'otel_spans';from=from || 'now-7d';thru=thru || 'now';compareFrom=compareFrom || 'now-14d';compareThru=compareThru || 'now-7d'
const query=(start,end,version)=>({datasetId,mode:'documents',from:start,thru:end,queryString:queryString || '',pageSize:1000,
    filters:version?[{field:{name:'service.version',op:'eq',value:version}}]:[]})
leftFrame={fields:[]};rightFrame={fields:[]};compareNotices=[]
for (const [side,start,end,version] of [['left',from,thru,leftVersion],['right',compareFrom,compareThru,rightVersion]]) {
    try {
        const result=ec.service.sync().name('org.moqui.report.ReportServices.run#Query').parameters({query:query(start,end,version)}).call()
        if (side==='left') leftFrame=(result.frames || [])[0] || {fields:[]}
        else rightFrame=(result.frames || [])[0] || {fields:[]}
        compareNotices.push(...(result.notices || []).map(notice=>side+': '+(notice.message || String(notice))))
    } catch (error) { ec.logger.error('Explore comparison '+side+' failed: '+String(error));compareNotices.push(side+': '+String(error)) }
}
